namespace Sankore.Modules.Leads.Domain;

using Sankore.Shared.Kernel;

/// <summary>
/// A unit of work generated by a business event (dispatch, score change, etc.)
/// or manually by a user. Ties together: type, priority, SLA, due date, and
/// the lead it relates to (US-M13-080).
/// </summary>
public sealed class CrmTask : ITenant
{
    public Guid Id { get; private set; }
    public Guid TenantId { get; private set; }
    public CrmTaskType Type { get; private set; }
    public CrmTaskPriority Priority { get; private set; }
    public string Title { get; private set; } = default!;
    public string? Description { get; private set; }

    /// <summary>
    /// What the task is about: a lead, a client or a KYC file — or nothing (an internal task).
    /// An opaque reference across modules, no foreign key, like <c>Appointment.ClientId</c>.
    /// </summary>
    public TaskEntityType? EntityType { get; private set; }
    public Guid? EntityId { get; private set; }

    /// <summary>
    /// Kept for the lead: dispatching, the lead's Tâches tab and every generated task read it.
    /// Always equal to <see cref="EntityId"/> when <see cref="EntityType"/> is Lead, null otherwise.
    /// </summary>
    public Guid? LeadId { get; private set; }

    /// <summary>Who created it; null for a task the system generated.</summary>
    public Guid? CreatedBy { get; private set; }
    public Guid? AssignedAgentId { get; private set; }
    public CrmTaskStatus Status { get; private set; }
    public DateTimeOffset DueAt { get; private set; }
    public DateTimeOffset? SlaDeadline { get; private set; }
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset? StartedAt { get; private set; }
    public DateTimeOffset? CompletedAt { get; private set; }

    /// <summary>Simple name of the integration event that triggered this task; null for manual tasks.</summary>
    public string? TriggerEventType { get; private set; }
    public Guid? TriggerEventId { get; private set; }

    /// <summary>
    /// Compatibility score (0-100) produced by the dispatching engine when
    /// this task was auto-dispatched via US-M13-081. Null for manual assignments.
    /// </summary>
    public double? CompatibilityScore { get; private set; }

    /// <summary>
    /// Per-factor breakdown JSON produced by CompatibilityScorer for the
    /// winning agent. Mirrors LeadAssignment.CompatibilityFactorsJson for
    /// the same explainability guarantee (US-M13-072 / US-M13-081).
    /// </summary>
    public string? CompatibilityFactorsJson { get; private set; }

    private CrmTask() { }

    public static CrmTask Create(
        Guid tenantId,
        CrmTaskType type,
        CrmTaskPriority priority,
        string title,
        DateTimeOffset dueAt,
        Guid? leadId = null,
        Guid? assignedAgentId = null,
        DateTimeOffset? slaDeadline = null,
        string? description = null,
        string? triggerEventType = null,
        Guid? triggerEventId = null)
        => new()
        {
            Id               = Guid.NewGuid(),
            TenantId         = tenantId,
            Type             = type,
            Priority         = priority,
            Title            = title,
            Description      = description,
            LeadId           = leadId,
            EntityType       = leadId.HasValue ? TaskEntityType.Lead : null,
            EntityId         = leadId,
            AssignedAgentId  = assignedAgentId,
            Status           = CrmTaskStatus.Pending,
            DueAt            = dueAt,
            SlaDeadline      = slaDeadline,
            CreatedAt        = DateTimeOffset.UtcNow,
            TriggerEventType = triggerEventType,
            TriggerEventId   = triggerEventId
        };

    /// <summary>
    /// Points a system task at a client rather than a lead — a project opened on an existing
    /// client has none. Ignored once the task is about a lead: dispatching reads <see cref="LeadId"/>.
    /// </summary>
    public CrmTask AboutClient(Guid clientId)
    {
        if (LeadId is null)
        {
            EntityType = TaskEntityType.Client;
            EntityId = clientId;
        }
        return this;
    }

    /// <summary>
    /// The task of a workflow « Tâche manuelle » step, about the circuit's record. Linked back to the
    /// step through <see cref="TriggerEventType"/> <c>workflow.step</c> and <see cref="TriggerEventId"/>
    /// = the instance step: completing it moves the circuit on.
    /// </summary>
    public static CrmTask ForWorkflowStep(
        Guid tenantId,
        string title,
        string description,
        TaskEntityType? entityType,
        Guid? entityId,
        Guid? assignedAgentId,
        DateTimeOffset dueAt,
        Guid instanceStepId,
        string triggerEventType)
    {
        var task = Create(
            tenantId, CrmTaskType.Generic, CrmTaskPriority.Medium,
            title.Length <= TitleMaxLength ? title : title[..TitleMaxLength], dueAt,
            leadId: entityType == TaskEntityType.Lead ? entityId : null,
            assignedAgentId: assignedAgentId,
            description: description,
            triggerEventType: triggerEventType,
            triggerEventId: instanceStepId);
        task.EntityType = entityId.HasValue ? entityType : null;
        task.EntityId = entityType.HasValue ? entityId : null;
        return task;
    }

    public const int TitleMaxLength = 200;
    public const int DescriptionMaxLength = 4000;

    /// <summary>
    /// A task created by a person, about anything or nothing. A lead also sets <see cref="LeadId"/>,
    /// so everything that reads the lead's tasks keeps seeing it.
    /// </summary>
    public static Result<CrmTask> CreateManual(
        Guid tenantId,
        Guid createdBy,
        CrmTaskType type,
        CrmTaskPriority priority,
        string title,
        DateTimeOffset dueAt,
        TaskEntityType? entityType,
        Guid? entityId,
        Guid? assignedAgentId,
        string? description,
        DateTimeOffset now)
    {
        if (string.IsNullOrWhiteSpace(title)) return Result.Fail<CrmTask>("TASK_TITLE_REQUIRED");
        if (title.Trim().Length > TitleMaxLength) return Result.Fail<CrmTask>("TASK_TITLE_TOO_LONG");
        if (description?.Trim().Length > DescriptionMaxLength) return Result.Fail<CrmTask>("TASK_DESCRIPTION_TOO_LONG");
        if (dueAt <= now) return Result.Fail<CrmTask>("TASK_DUE_IN_PAST");
        if (entityType.HasValue != (entityId is { } id && id != Guid.Empty)) return Result.Fail<CrmTask>("TASK_ENTITY_INCOMPLETE");

        var task = Create(
            tenantId, type, priority, title.Trim(), dueAt,
            leadId: entityType == TaskEntityType.Lead ? entityId : null,
            assignedAgentId: assignedAgentId,
            description: string.IsNullOrWhiteSpace(description) ? null : description.Trim());

        task.EntityType = entityType;
        task.EntityId = entityType.HasValue ? entityId : null;
        task.CreatedBy = createdBy;
        task.CreatedAt = now;
        return Result.Ok(task);
    }

    /// <summary>Title, description and priority — refused once the task is closed.</summary>
    public Result UpdateDetails(string title, string? description, CrmTaskPriority priority)
    {
        if (Status is CrmTaskStatus.Completed or CrmTaskStatus.Cancelled) return Result.Fail("TASK_CLOSED");
        if (string.IsNullOrWhiteSpace(title)) return Result.Fail("TASK_TITLE_REQUIRED");
        if (title.Trim().Length > TitleMaxLength) return Result.Fail("TASK_TITLE_TOO_LONG");
        if (description?.Trim().Length > DescriptionMaxLength) return Result.Fail("TASK_DESCRIPTION_TOO_LONG");

        Title = title.Trim();
        Description = string.IsNullOrWhiteSpace(description) ? null : description.Trim();
        Priority = priority;
        return Result.Ok();
    }

    public bool IsClosed => Status is CrmTaskStatus.Completed or CrmTaskStatus.Cancelled;

    public Result Complete()
    {
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail("TASK_CANCELLED");
        if (Status == CrmTaskStatus.Completed)  return Result.Fail("TASK_ALREADY_COMPLETED");
        Status      = CrmTaskStatus.Completed;
        CompletedAt = DateTimeOffset.UtcNow;
        return Result.Ok();
    }

    public Result Cancel()
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled) return Result.Fail("TASK_ALREADY_CANCELLED");
        Status = CrmTaskStatus.Cancelled;
        return Result.Ok();
    }

    public Result StartProgress()
    {
        if (Status != CrmTaskStatus.Pending) return Result.Fail("TASK_NOT_PENDING");
        Status    = CrmTaskStatus.InProgress;
        StartedAt = DateTimeOffset.UtcNow;
        return Result.Ok();
    }

    /// <summary>
    /// Manual assignment — bypasses the scoring engine. Used for admin
    /// overrides and direct task hand-offs. No audit score is recorded.
    /// </summary>
    public void AssignTo(Guid agentId) => AssignedAgentId = agentId;

    /// <summary>
    /// Scored dispatch — assigns the task to the best-ranked agent and
    /// stores the compatibility breakdown for post-hoc auditability
    /// (US-M13-081). A cancelled or completed task cannot be dispatched.
    /// </summary>
    public Result Dispatch(Guid agentId, double compatibilityScore, string compatibilityFactorsJson)
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail("TASK_CANCELLED");

        AssignedAgentId          = agentId;
        CompatibilityScore       = compatibilityScore;
        CompatibilityFactorsJson = compatibilityFactorsJson;
        return Result.Ok();
    }

    /// <summary>
    /// Agent declines the task (US-M13-084). Unassigns the agent and resets
    /// status to Pending so the task re-enters the dispatch pool.
    /// Returns the declining agent's ID for exclusion-cache and capacity-cache handling.
    /// </summary>
    public Result<Guid> Decline()
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail<Guid>("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail<Guid>("TASK_CANCELLED");
        if (AssignedAgentId is null)             return Result.Fail<Guid>("TASK_NOT_ASSIGNED");

        var agentId     = AssignedAgentId.Value;
        AssignedAgentId = null;
        Status          = CrmTaskStatus.Pending;
        StartedAt       = null;

        // Clear dispatch audit — stale after decline
        CompatibilityScore       = null;
        CompatibilityFactorsJson = null;

        return Result.Ok(agentId);
    }

    /// <summary>
    /// Audited reassignment (US-M13-083). Changes the assigned agent and optionally
    /// extends the SLA deadline. Cannot reassign a completed or cancelled task.
    /// Returns the previous agent id so the caller can invalidate capacity caches.
    /// </summary>
    public Result<Guid?> Reassign(
        Guid newAgentId, DateTimeOffset? newSlaDeadline = null, DateTimeOffset? newDueAt = null)
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail<Guid?>("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail<Guid?>("TASK_CANCELLED");

        var previous    = AssignedAgentId;
        AssignedAgentId = newAgentId;

        if (newSlaDeadline.HasValue)
            SlaDeadline = newSlaDeadline;
        if (newDueAt.HasValue)
            DueAt = newDueAt.Value;

        return Result.Ok(previous);
    }

    /// <summary>
    /// The agent moves when they will do the work — « reporter à demain », or a day's first
    /// contacts spread over the week. Only the due date moves: <see cref="SlaDeadline"/> is a
    /// commitment made to the prospect, and an agent postponing their own task must not quietly
    /// postpone it too. A task moved past its SLA therefore shows as late, which is the truth.
    /// </summary>
    public Result Reschedule(DateTimeOffset newDueAt, DateTimeOffset now)
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail("TASK_CANCELLED");
        if (newDueAt <= now)                    return Result.Fail("TASK_DUE_IN_PAST");

        DueAt = newDueAt;
        return Result.Ok();
    }

    /// <summary>
    /// SLA escalation: the agent keeps the task and its deadline moves to the escalated
    /// assignment's. The due date follows when it would otherwise fall before the new deadline —
    /// a task due before its own SLA reads as late on the agent's list for no reason.
    /// </summary>
    public Result ExtendSla(DateTimeOffset newSlaDeadline)
    {
        if (Status == CrmTaskStatus.Completed) return Result.Fail("TASK_ALREADY_COMPLETED");
        if (Status == CrmTaskStatus.Cancelled)  return Result.Fail("TASK_CANCELLED");

        SlaDeadline = newSlaDeadline;
        if (DueAt < newSlaDeadline)
            DueAt = newSlaDeadline;

        return Result.Ok();
    }
}
